import { cssFontStack, ms, px } from './format';
import {
  breakpoint,
  color,
  containerMax,
  fontFamily,
  fontSize,
  fontWeight,
  motion,
  radius,
  shadow,
  size,
  spacing,
} from './tokens';

/**
 * Tailwind CSS v4 theme for the web apps and ui-web. Every default namespace the design system
 * owns is reset first, so only token-backed utilities exist: `bg-red-500`, `p-7`, `text-sm` or
 * `rounded-md` simply do not compile. Import after `@import "tailwindcss"`.
 */
export function getTailwindThemeCss(): string {
  const lines: string[] = [
    '/* Generated by @suskii/design-tokens. Do not edit; change src/tokens.ts instead. */',
    '',
    '@theme static {',
    '  --color-*: initial;',
    '  --font-*: initial;',
    '  --text-*: initial;',
    '  --font-weight-*: initial;',
    '  --spacing: initial;',
    '  --spacing-*: initial;',
    '  --radius-*: initial;',
    '  --shadow-*: initial;',
    '  --breakpoint-*: initial;',
    '  --container-*: initial;',
    '  --ease-*: initial;',
    '',
    ...Object.entries(color).map(([name, value]) => `  --color-${name}: ${value};`),
    '',
    ...Object.entries(fontFamily.web).map(
      ([name, stack]) => `  --font-${name}: ${cssFontStack(stack)};`,
    ),
    ...Object.entries(fontWeight).map(([name, value]) => `  --font-weight-${name}: ${value};`),
    ...Object.entries(fontSize).flatMap(([name, { size, lineHeight }]) => [
      `  --text-${name}: ${px(size)};`,
      `  --text-${name}--line-height: ${lineHeight};`,
    ]),
    '',
    ...Object.entries(spacing).map(([name, value]) => `  --spacing-${name}: ${px(value)};`),
    ...Object.entries(radius).map(([name, value]) => `  --radius-${name}: ${px(value)};`),
    ...Object.entries(shadow).map(([name, value]) => `  --shadow-${name}: ${value};`),
    ...Object.entries(breakpoint).map(([name, value]) => `  --breakpoint-${name}: ${px(value)};`),
    `  --container-page: ${px(containerMax)};`,
    `  --container-popover: ${px(size.popover)};`,
    `  --container-dialog: ${px(size.dialog)};`,
    `  --size-menu: ${px(size.menu)};`,
    ...Object.entries(motion.easing).map(([name, value]) => `  --ease-${name}: ${value};`),
    ...Object.entries(motion.duration).map(
      ([name, value]) => `  --duration-${name}: ${ms(value)};`,
    ),
    '}',
    '',
    ...Object.keys(motion.duration).flatMap((name) => [
      `@utility duration-${name} {`,
      `  transition-duration: var(--duration-${name});`,
      '}',
      '',
    ]),
    '@utility max-h-menu {',
    '  max-height: var(--size-menu);',
    '}',
    '',
    '/* Solid 2px outline (passes WCAG 1.4.11) plus the spec focus_ring as a soft halo. ADR-004. */',
    '@utility focus-ring {',
    '  outline: 2px solid var(--color-focus);',
    '  outline-offset: 2px;',
    '  box-shadow: 0 0 0 5px var(--color-focus-ring);',
    '}',
    '',
    '@layer base {',
    '  @media (prefers-reduced-motion: reduce) {',
    '    *,',
    '    ::before,',
    '    ::after {',
    '      animation-duration: 0.01ms !important;',
    '      animation-iteration-count: 1 !important;',
    '      transition-duration: 0.01ms !important;',
    '      scroll-behavior: auto !important;',
    '    }',
    '  }',
    '}',
    '',
  ];
  return lines.join('\n');
}
